// Render the fleet status page. Add ?format=json to the URL to get JSON instead.
// Keep OFFLINE_AFTER_MINUTES equal to the value in the other fleet workflows.
const OFFLINE_AFTER_MINUTES = 15;

const nowMs = Date.now();
const query = $('Status page').first().json.query ?? {};
const toMs = (value) => (value ? new Date(value).getTime() : null);

const devices = $('List devices')
	.all()
	.map((item) => item.json)
	.filter((row) => row.deviceId)
	.map((row) => {
		const lastSeenMs = toMs(row.lastSeenAt);
		// The watchdog runs every few minutes, so check the age here too.
		const online =
			row.status === 'online' &&
			lastSeenMs !== null &&
			nowMs - lastSeenMs <= OFFLINE_AFTER_MINUTES * 60000;
		return { ...row, online };
	})
	.sort((a, b) => Number(b.online) - Number(a.online) || toMs(b.lastSeenAt) - toMs(a.lastSeenAt));

const events = $input
	.all()
	.map((item) => item.json)
	.filter((row) => row.deviceId);

const summary = {
	total: devices.length,
	online: devices.filter((d) => d.online).length,
	offline: devices.filter((d) => !d.online).length,
	cameOnlineToday: new Set(
		events
			.filter((e) => e.event === 'online' && nowMs - toMs(e.occurredAt) < 24 * 3600000)
			.map((e) => e.deviceId),
	).size,
	generatedAt: new Date(nowMs).toISOString(),
};

if (query.format === 'json') {
	return [
		{
			json: {
				contentType: 'application/json; charset=utf-8',
				body: JSON.stringify({ summary, devices, events }, null, 2),
			},
		},
	];
}

const esc = (value) =>
	String(value ?? '')
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&#39;');

const ago = (value) => {
	const ms = toMs(value);
	if (ms === null) return '<span class="muted">never</span>';
	const minutes = Math.round((nowMs - ms) / 60000);
	let text;
	if (minutes < 1) text = 'just now';
	else if (minutes < 60) text = `${minutes} min ago`;
	else if (minutes < 48 * 60) text = `${Math.round(minutes / 60)} h ago`;
	else text = `${Math.round(minutes / 1440)} d ago`;
	return `<time datetime="${esc(new Date(ms).toISOString())}" title="${esc(new Date(ms).toISOString())}">${text}</time>`;
};

const badge = (online) =>
	online ? '<span class="badge on">Online</span>' : '<span class="badge off">Offline</span>';

const deviceRows = devices
	.map(
		(d) => `<tr data-search="${esc([d.deviceId, d.hostname, d.assetTag, d.rentedTo, d.osUser, d.serialNumber].join(' ').toLowerCase())}">
<td>${badge(d.online)}</td>
<td><strong>${esc(d.assetTag || d.hostname || d.deviceId)}</strong><div class="muted">${[d.hostname, d.serialNumber || d.deviceId].filter(Boolean).map(esc).join(' · ')}</div></td>
<td>${esc(d.rentedTo) || '<span class="muted">-</span>'}</td>
<td>${esc(d.osUser) || '<span class="muted">-</span>'}</td>
<td>${ago(d.lastOnlineAt)}</td>
<td>${ago(d.lastSeenAt)}</td>
<td>${ago(d.lastOfflineAt)}</td>
<td class="num">${esc(d.onlineCount ?? 0)}</td>
<td>${esc(d.localIp)}<div class="muted">${esc(d.publicIp)}</div></td>
</tr>`,
	)
	.join('\n');

const eventLabels = { online: 'Came online', offline: 'Went offline', logon: 'User logged on', shutdown: 'Shut down', boot: 'Booted' };
const eventRows = events
	.map(
		(e) => `<tr data-search="${esc([e.deviceId, e.hostname, e.osUser].join(' ').toLowerCase())}">
<td>${ago(e.occurredAt)}</td>
<td><span class="dot ${esc(e.event)}"></span>${esc(eventLabels[e.event] ?? e.event)}<span class="muted"> via ${esc(e.trigger)}</span></td>
<td>${esc(e.hostname || e.deviceId)}</td>
<td>${esc(e.osUser) || '<span class="muted">-</span>'}</td>
<td class="num">${e.offlineMinutes === null || e.offlineMinutes === undefined ? '<span class="muted">-</span>' : esc(e.offlineMinutes)}</td>
</tr>`,
	)
	.join('\n');

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="60">
<title>Rental fleet status</title>
<style>
:root { --bg: #f6f7f9; --card: #fff; --text: #1d2330; --muted: #6b7280; --line: #e5e7eb; --on: #15803d; --on-bg: #dcfce7; --off: #b91c1c; --off-bg: #fee2e2; }
@media (prefers-color-scheme: dark) { :root { --bg: #0f1115; --card: #181b22; --text: #e5e7eb; --muted: #9ca3af; --line: #2a2f3a; --on: #4ade80; --on-bg: #14361f; --off: #f87171; --off-bg: #3b1616; } }
* { box-sizing: border-box; }
body { margin: 0; padding: 24px 16px; background: var(--bg); color: var(--text); font: 14px/1.45 system-ui, -apple-system, Segoe UI, Roboto, sans-serif; }
main { max-width: 1200px; margin: 0 auto; }
h1 { font-size: 22px; margin: 0 0 4px; } h2 { font-size: 16px; margin: 28px 0 8px; }
.muted { color: var(--muted); font-size: 12px; }
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin: 16px 0; }
.stat { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; }
.stat b { display: block; font-size: 26px; font-variant-numeric: tabular-nums; }
.wrap { overflow-x: auto; background: var(--card); border: 1px solid var(--line); border-radius: 10px; }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--line); vertical-align: top; white-space: nowrap; }
th { font-size: 12px; color: var(--muted); font-weight: 600; }
tr:last-child td { border-bottom: 0; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.badge { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 600; }
.badge.on { color: var(--on); background: var(--on-bg); } .badge.off { color: var(--off); background: var(--off-bg); }
.dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; background: var(--muted); }
.dot.online { background: var(--on); } .dot.offline, .dot.shutdown { background: var(--off); }
input[type=search] { width: 100%; max-width: 360px; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--line); background: var(--card); color: var(--text); font: inherit; }
</style>
</head>
<body>
<main>
<h1>Rental fleet status</h1>
<div class="muted">Updated ${esc(summary.generatedAt)} · refreshes every minute · offline after ${OFFLINE_AFTER_MINUTES} min without a check-in</div>
<div class="stats">
<div class="stat"><b>${summary.total}</b>Laptops</div>
<div class="stat"><b style="color:var(--on)">${summary.online}</b>Online now</div>
<div class="stat"><b style="color:var(--off)">${summary.offline}</b>Offline</div>
<div class="stat"><b>${summary.cameOnlineToday}</b>Came online in 24 h</div>
</div>
<input type="search" id="q" placeholder="Filter by hostname, asset tag, renter or user" aria-label="Filter">
<h2>Laptops</h2>
<div class="wrap"><table>
<thead><tr><th>Status</th><th>Laptop</th><th>Rented to</th><th>User</th><th>Last came online</th><th>Last seen</th><th>Last offline</th><th class="num">Sessions</th><th>IP</th></tr></thead>
<tbody>${deviceRows || '<tr><td colspan="9" class="muted">No laptop has checked in yet.</td></tr>'}</tbody>
</table></div>
<h2>Recent activity</h2>
<div class="wrap"><table>
<thead><tr><th>When</th><th>Event</th><th>Laptop</th><th>User</th><th class="num">Was offline (min)</th></tr></thead>
<tbody>${eventRows || '<tr><td colspan="5" class="muted">No activity yet.</td></tr>'}</tbody>
</table></div>
</main>
<script>
document.getElementById('q').addEventListener('input', (e) => {
	const q = e.target.value.trim().toLowerCase();
	document.querySelectorAll('tr[data-search]').forEach((row) => {
		row.hidden = q !== '' && !row.dataset.search.includes(q);
	});
});
</script>
</body>
</html>`;

return [{ json: { contentType: 'text/html; charset=utf-8', body: html } }];
